function addRow(id){let body=document.getElementById(id),i=Date.now()+Math.floor(Math.random()*1000),tr=document.createElement('tr');for(let key of ['name','spec','unit','quantity']){let td=document.createElement('td'),e=document.createElement('input');e.name=id+'['+i+']['+key+']';if(key==='quantity'){e.type='number';e.min='.01';e.step='any'}td.append(e);tr.append(td)}let td=document.createElement('td'),b=document.createElement('button');b.type='button';b.textContent='×';b.onclick=()=>tr.remove();td.append(b);tr.append(td);body.append(tr)}
</script></body></html>